# POST /api/sheets/{sheetId}/generate-fy — add the fiscal year's twelve monthly periods, from the sheet's fiscal year start
# month of the year on, exactly as generate-periods does (a month whose name the sheet already has, or whose days overlap
# a period, is left out). Body: { "year": "yyyy" } (a fiscal year is named by the calendar year its first day falls in).
# A year that is not four digits is refused. Responds { "generated": n }.
guard:
  class: net.officefloor.hq.app.role.GuardViewer
  next: archived
archived:
  class: net.officefloor.hq.app.sheet.GuardArchived
  next: validate
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadOrCreateSheet
  govern: [ transaction ]
  next: generate
generate:
  class: net.officefloor.hq.app.period.GenerateFiscalYear
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodsGenerated
  govern: [ transaction ]
  next: respond
respond:
